import Database, { Database as DatabaseType } from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';
import { existsSync, mkdirSync } from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const dbPath = process.env.DATABASE_PATH || path.join(__dirname, '../../data/database.sqlite');

// Create parent directory if it doesn't exist
const dbDir = path.dirname(dbPath);
if (!existsSync(dbDir)) {
  mkdirSync(dbDir, { recursive: true });
}

export const db: DatabaseType = new Database(dbPath);

// Enable foreign keys
db.pragma('foreign_keys = ON');

export function initDatabase() {
  // Create tables
  db.exec(`
    -- Question Types table (administrable)
    CREATE TABLE IF NOT EXISTS question_types (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      description TEXT,
      scoring_mode TEXT NOT NULL DEFAULT 'match' CHECK(scoring_mode IN ('match', 'consensus', 'proximity', 'none', 'individual', 'ranking')),
      input_type TEXT NOT NULL DEFAULT 'options' CHECK(input_type IN ('options', 'binary', 'scale', 'text', 'who', 'qcm', 'image_choice', 'month_select', 'duration', 'ranking', 'plus_moins', 'agree_disagree')),
      icon TEXT,
      color TEXT,
      active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT (datetime('now'))
    );

    -- Categories table (administrable)
    CREATE TABLE IF NOT EXISTS categories (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      icon TEXT,
      color TEXT,
      description TEXT,
      active INTEGER DEFAULT 1,
      sort_order INTEGER DEFAULT 0
    );

    -- Rooms table
    CREATE TABLE IF NOT EXISTS rooms (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT UNIQUE NOT NULL,
      player1_name TEXT,
      player2_name TEXT,
      player1_gender TEXT CHECK(player1_gender IN ('M', 'F')),
      player2_gender TEXT CHECK(player2_gender IN ('M', 'F')),
      status TEXT DEFAULT 'waiting' CHECK(status IN ('waiting', 'playing', 'finished')),
      created_at TEXT DEFAULT (datetime('now')),
      last_activity TEXT DEFAULT (datetime('now'))
    );

    -- Questions table (updated with foreign keys)
    CREATE TABLE IF NOT EXISTS questions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      type TEXT NOT NULL,
      category TEXT NOT NULL,
      text TEXT NOT NULL,
      options TEXT,
      option_a TEXT,
      option_b TEXT,
      emoji_a TEXT,
      emoji_b TEXT,
      correct_answer TEXT,
      timer INTEGER DEFAULT 20,
      active INTEGER DEFAULT 1
    );

    -- Games table
    CREATE TABLE IF NOT EXISTS games (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      room_id INTEGER NOT NULL,
      started_at TEXT DEFAULT (datetime('now')),
      finished_at TEXT,
      score_player1 INTEGER DEFAULT 0,
      score_player2 INTEGER DEFAULT 0,
      FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE
    );

    -- Answers table
    CREATE TABLE IF NOT EXISTS answers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      game_id INTEGER NOT NULL,
      question_id INTEGER NOT NULL,
      player_id INTEGER NOT NULL CHECK(player_id IN (1, 2)),
      answer TEXT NOT NULL,
      answered_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE,
      FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
    );

    -- Admin table
    CREATE TABLE IF NOT EXISTS admin (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL
    );

    -- Create indexes
    CREATE INDEX IF NOT EXISTS idx_rooms_code ON rooms(code);
    CREATE INDEX IF NOT EXISTS idx_rooms_status ON rooms(status);
    CREATE INDEX IF NOT EXISTS idx_games_room ON games(room_id);
    CREATE INDEX IF NOT EXISTS idx_answers_game ON answers(game_id);
    CREATE INDEX IF NOT EXISTS idx_questions_active ON questions(active);
    CREATE INDEX IF NOT EXISTS idx_categories_active ON categories(active);
    CREATE INDEX IF NOT EXISTS idx_question_types_active ON question_types(active);
  `);

  // Run migrations for existing databases
  runMigrations();

  // Insert default question types if not exists
  initDefaultQuestionTypes();
  initDefaultCategories();
  initDefaultQuestions();
  addNewQuestionsV2();
  mergeLegacyCategories();
  purgeSyntheticQuestions();
  fixQuestionInputTypes();

  console.log('Database initialized successfully');
}

/**
 * Certaines questions historiques portent un code de categorie qui n'a jamais
 * ete enregistre dans la table categories. Le selecteur de themes ne listant que
 * cette table, ces questions n'etaient jamais jouables. On les rattache a la
 * categorie equivalente (les orphelines les plus petites tenaient sur 3 questions,
 * trop peu pour constituer un theme viable).
 * Idempotent : peut tourner a chaque demarrage.
 */
/**
 * Le mode "A l'envers" insere une question synthetique (inactive) a chaque
 * manche, et c'est un mode sans fin : sans purge, la table questions grossit
 * indefiniment (constat de l'audit d'architecture). On nettoie au demarrage ;
 * la cle etrangere answers.question_id est en ON DELETE CASCADE, l'historique
 * de ces manches synthetiques part avec, ce qui est voulu.
 */
/**
 * Repare le type de saisie des questions DEJA EN BASE.
 *
 * Les fichiers data/ ont ete corriges, mais import-thematic saute toute
 * question dont (texte, categorie) existe deja : une base peuplee avant la
 * correction gardait donc l'ancien type pour toujours. Resultat vu en prod :
 * "Decris la position qui te fait le plus jouir." servie avec un curseur 1-10.
 *
 * Regles, alignees sur database.ts et sur les tests de contenu :
 *  - enonce descriptif ("Decris...", "Quel mot...", "Comment...") => C (texte)
 *  - enonce "sur 10 / a quel point / quel pourcentage"            => D (echelle)
 * Idempotent : peut tourner a chaque demarrage.
 */
function fixQuestionInputTypes() {
  const descriptif = /^(décris|decris|quel mot|comment |qu'est-ce qui|qu'est-ce que|quel conseil|raconte|avoue|décrivez)/i;
  const echelle = /(sur 10|note sur 10|à quel point|a quel point|quel pourcentage|à quel pourcentage)/i;

  const rows = db.prepare("SELECT id, type, text FROM questions WHERE type IN ('C','D')")
    .all() as { id: number; type: string; text: string }[];

  const toText = db.prepare("UPDATE questions SET type = 'C' WHERE id = ?");
  const toScale = db.prepare("UPDATE questions SET type = 'D' WHERE id = ?");
  let fixed = 0;

  for (const r of rows) {
    const t = (r.text || '').trim();
    if (r.type === 'D' && descriptif.test(t) && !echelle.test(t)) {
      toText.run(r.id); fixed++;
    } else if (r.type === 'C' && echelle.test(t)) {
      toScale.run(r.id); fixed++;
    }
  }
  if (fixed > 0) console.log(`Types de saisie corriges en base : ${fixed} question(s)`);
}

function purgeSyntheticQuestions() {
  const purged = db.prepare(
    "DELETE FROM questions WHERE active = 0 AND text LIKE '%De quelle question cette réponse vient-elle%'"
  ).run().changes;
  if (purged > 0) console.log(`Purge: ${purged} questions synthetiques du mode inverse supprimees`);
}

function mergeLegacyCategories() {
  const merges: Record<string, string> = {
    connaissance: 'couple',        // "Selon toi, il/elle est plutot..."
    amour: 'couple',               // "Tu te sens aime(e) quand..."
    quotidien: 'habitudes',        // "Ta matinee ideale..."
    comportement: 'habitudes',     // "Comment ton partenaire reagit face au stress"
    sextoys: 'coquin',
    confessions: 'coquin',
    seduction: 'preliminaires',
    massage: 'preliminaires',
    anal: 'sodomie'                // doublon avec la categorie sodomie existante
  };

  const update = db.prepare('UPDATE questions SET category = ? WHERE category = ?');
  let moved = 0;
  for (const [from, to] of Object.entries(merges)) {
    moved += update.run(to, from).changes;
  }
  if (moved > 0) {
    console.log(`Categories: ${moved} questions rattachees a une categorie jouable`);
  }
}

function runMigrations() {
  // Check if columns exist by querying table info
  const roomColumns = db.prepare("PRAGMA table_info(rooms)").all() as { name: string }[];
  const roomColumnNames = roomColumns.map(c => c.name);

  // Migration: Add gender columns to rooms table
  if (!roomColumnNames.includes('player1_gender')) {
    db.exec("ALTER TABLE rooms ADD COLUMN player1_gender TEXT CHECK(player1_gender IN ('M', 'F'))");
    console.log('Migration: Added player1_gender column to rooms');
  }
  // Jetons de session (audit securite) : authentifient room:reconnect.
  if (!roomColumnNames.includes('player1_token')) {
    db.exec("ALTER TABLE rooms ADD COLUMN player1_token TEXT");
    db.exec("ALTER TABLE rooms ADD COLUMN player2_token TEXT");
    console.log('Migration: Added session token columns to rooms');
  }
  if (!roomColumnNames.includes('player2_gender')) {
    db.exec("ALTER TABLE rooms ADD COLUMN player2_gender TEXT CHECK(player2_gender IN ('M', 'F'))");
    console.log('Migration: Added player2_gender column to rooms');
  }

  // Check questions table for correct_answer column
  const questionColumns = db.prepare("PRAGMA table_info(questions)").all() as { name: string }[];
  const questionColumnNames = questionColumns.map(c => c.name);

  if (!questionColumnNames.includes('correct_answer')) {
    db.exec("ALTER TABLE questions ADD COLUMN correct_answer TEXT");
    console.log('Migration: Added correct_answer column to questions');
  }
}

