export function cleanupExpiredRooms() {
  const result = db.prepare(`
    DELETE FROM rooms
    WHERE datetime(last_activity) < datetime('now', '-7 days')
  `).run();

  if (result.changes > 0) {
    console.log(`Cleaned up ${result.changes} expired rooms`);
  }
}
